cd /home/user/RL_Study/report-gepa/runs/originals/makeup-shades && python3 - <<'PY'
import json
facts=json.load(open('facts.json'))
for f in facts:
    if f['id']=='bestsellers-10-20-band':
        f['source']="(and Maybelline and L'Oréal actually cover the 10-20 lightness range that Fenty doesn’t!)"
with open('facts.json','w') as fh:
    json.dump(facts, fh, ensure_ascii=False, indent=2)
skipped=json.load(open('skipped.json'))
for s in skipped:
    if s['source'].startswith('Its claim to fame'):
        s['source']="Its claim to fame: the foundation launched with 40 shades"
with open('skipped.json','w') as fh:
    json.dump(skipped, fh, ensure_ascii=False, indent=2)
print('done')
